css:
.sl-article-grid {
    background-color: var(--smartlearn-bg);
    padding-block: 3rem;
}
@media (min-width: 992px) {
    .sl-article-grid { padding-block: 6rem; }
}

.sl-article-grid .sl-text-primary { color: var(--smartlearn-primary) !important; }
.sl-article-grid .sl-text-emphasis { color: var(--smartlearn-text) !important; }
.sl-article-grid .sl-text-muted { color: var(--smartlearn-text-muted) !important; }
.sl-article-grid .sl-bg-main { background-color: var(--smartlearn-bg) !important; }
.sl-article-grid .sl-bg-card { background-color: var(--smartlearn-card-bg) !important; border: 1px solid var(--smartlearn-card-border) !important; }
.sl-article-grid .sl-border { border-color: var(--smartlearn-card-border) !important; }

.sl-article-grid .sl-btn-badge {
    background-color: var(--smartlearn-btn-bg);
    color: var(--smartlearn-btn-text);
}

.sl-article-grid .sl-btn-cta {
    background-color: var(--smartlearn-btn-bg);
    color: var(--smartlearn-btn-text);
    border: 1px solid transparent;
    transition: background-color 0.2s ease;
}
.sl-article-grid .sl-btn-cta:hover,
.sl-article-grid .sl-btn-cta:focus-visible {
    background-color: var(--smartlearn-btn-hover-bg);
    color: var(--smartlearn-btn-text);
}

.sl-article-grid .sl-banner-icon {
    width: 56px;
    height: 56px;
    background-color: color-mix(in srgb, var(--smartlearn-primary) 14%, transparent);
    color: var(--smartlearn-primary);
}
.sl-article-grid .sl-grid-banner {
    border: 2px solid var(--smartlearn-primary) !important;
}

.sl-article-grid .sl-focus-ring:focus-visible {
    outline: 3px solid var(--smartlearn-primary);
    outline-offset: 3px;
}

/* CSS Grid Layout */
.sl-article-grid .sl-masonry-grid {
    display: grid;
    grid-template-columns: 1fr;
    gap: 1.5rem;
}
.sl-article-grid .sl-item-large .sl-item-media {
    height: 280px;
}

@media (min-width: 768px) {
    .sl-article-grid .sl-masonry-grid {
        grid-template-columns: repeat(2, 1fr);
    }
    .sl-article-grid .sl-item-large,
    .sl-article-grid .sl-grid-banner {
        grid-column: 1 / -1;
    }
}

@media (min-width: 992px) {
    .sl-article-grid .sl-masonry-grid {
        grid-template-columns: repeat(3, 1fr);
    }
    .sl-article-grid .sl-item-large {
        grid-column: span 2;
        grid-row: span 2;
    }
    .sl-article-grid .sl-item-large .sl-item-media {
        flex: 1 1 auto;
        min-height: 360px;
        height: auto;
    }
    .sl-article-grid .sl-grid-banner {
        grid-column: 1 / -1;
    }
}

/* Hover effects and overlays */
.sl-article-grid .sl-hover-zoom {
    transition: transform 0.6s ease;
}
@media (hover: hover) and (prefers-reduced-motion: no-preference) {
    .sl-article-grid .sl-grid-item:hover .sl-hover-zoom {
        transform: scale(1.05);
    }
}
@media (prefers-reduced-motion: reduce) {
    .sl-article-grid .sl-hover-zoom,
    .sl-article-grid .sl-btn-cta { transition: none; }
}

.sl-article-grid .sl-gradient-overlay-bottom {
    background: linear-gradient(to top, rgba(15, 23, 42, 0.88) 0%, rgba(15, 23, 42, 0.35) 60%, transparent 100%);
}

[dir="rtl"] .sl-article-grid .sl-rtl-flip {
    transform: scaleX(-1);
}
